            $low = $this->safe_number($history, 0);
            $open = $this->safe_number($history, strlen($history) - 1);
            for ($i = 1; $i < count($history); $i++) {
                $price = $this->safe_number($history, $i);
                $high = max ($high, $price);
                $low = min ($low, $price);
